replacements.new:
roots:=[]string{filepath.Join(os.Getenv("APPDATA"),"npm")}
if shim,e:=exec.LookPath("codex.cmd");e==nil{roots=append(roots,filepath.Dir(shim))}
unique:=map[string]string{}
for _,root:=range roots{
 for _,pattern:=range []string{
  filepath.Join(root,"node_modules","@openai","codex","vendor","*","codex","codex.exe"),
  filepath.Join(root,"node_modules","@openai","codex","node_modules","@openai","codex-win32-*","vendor","*","bin","codex.exe"),
 }{matches,_:=filepath.Glob(pattern);for _,match:=range matches{unique[strings.ToLower(filepath.Clean(match))]=match}}
}
if len(unique)!=1{return nil,errors.New("CODEX_EXECUTABLE_UNAVAILABLE")}
for _,match:=range unique{executable=match}
